<script setup>
import { $api } from '@/utils/api'
const meta=ref({members:[]}),facilities=ref([]),result=ref(null),error=ref('')
const form=reactive({member_id:null,facility_id:null,starts_at:'',ends_at:'',guest_count:0})
onMounted(async()=>{[meta.value,facilities.value]=await Promise.all([$api('/booking/facilities/meta'),$api('/booking/facilities')])})
async function run(){try{result.value=await $api('/booking/simulate',{method:'POST',body:form})}catch(e){error.value=e?.data?.message||'Simulation failed.'}}
</script>
<template><div><div class="mb-6"><h3 class="text-h3">Booking rule simulator</h3><p class="text-medium-emphasis">Uses the same backend evaluator as real holds and confirmation.</p></div><VAlert v-if="error" type="error">{{error}}</VAlert><VCard><VCardText><VRow><VCol cols="12" md="3"><VSelect v-model="form.member_id" :items="meta.members" item-title="display_name" item-value="id" label="Member"/></VCol><VCol cols="12" md="3"><VSelect v-model="form.facility_id" :items="facilities" item-title="name" item-value="id" label="Facility"/></VCol><VCol cols="12" md="3"><VTextField v-model="form.starts_at" type="datetime-local" label="Starts"/></VCol><VCol cols="12" md="3"><VTextField v-model="form.ends_at" type="datetime-local" label="Ends"/></VCol></VRow><VBtn @click="run">Run simulator</VBtn></VCardText></VCard><VCard v-if="result" class="mt-6"><VCardTitle>{{result.eligible?'Eligible':'Blocked'}} · {{result.profile.profile}}</VCardTitle><VCardText><VTable><thead><tr><th>Rule</th><th>Result</th><th>Explanation</th></tr></thead><tbody><tr v-for="check in result.checks" :key="check.code"><td>{{check.code}}</td><td>{{check.passed?'Pass':'Fail'}}</td><td>{{check.member_message}}</td></tr></tbody></VTable><pre class="pa-4 bg-surface-variant">{{JSON.stringify({policies:result.policies,price:result.price,allowance:result.allowance,cancellation:result.cancellation},null,2)}}</pre></VCardText></VCard></div></template>
